/** WKS-PARAMETROS (USING de la PROCEDURE DIVISION) más el modo que llega en TASKVALUE. */
public record ParametrosDepuracion(
        int sistema,                  // 9(03)
        LocalDate fecha,              // 9(08) AAAAMMDD; null si viene en ceros (depuración masiva)
        int numProceso,               // 9(03)
        int numRegIni,                // 9(02)
        int numRegFin,                // 9(03)
        ModoDepuracion modo) {}       // TASKVALUE: 1 regresa fecha, 2 sincroniza con S500, otro depura

public enum ModoDepuracion {
    REGRESA_FECHA, SINCRONIZA_S500, DEPURA;
    static ModoDepuracion de(long taskValue) {
        return taskValue == 1 ? REGRESA_FECHA : taskValue == 2 ? SINCRONIZA_S500 : DEPURA;
    }
}

# application.yml  (WKS-PROCESOSLIN y WKS-PROCESOSNNN dejan de estar compilados)
p196:
  procesos:
    s151: [0, 52, 195, 196]                          # "PRELINEA", 4 procesos
    otros: [1, 152, 172, 178, 197, 104, 122, 130, 131]  # "NNN", 9 procesos
  proceso-registro-inicial-1: 196                    # W77-REGINI = 1
  proceso-marca-reinicio: 197                        # se marca B05-SIS-FCHINI = 1
  fecha-minima-valida: 4                             # B05-SIS-FCHPRO > 3

@Configuration
public class DepuracionJobConfig {

    /** 000100-INICIO: un solo programa con tres comportamientos según TASKVALUE. */
    @Bean
    Job depuraControl(JobRepository repo, Step inicializa, JobExecutionDecider porModo,
                      Step regresaFecha, Step sincronizaS500, Step depura) {
        return new JobBuilder("S151P196", repo)
                .start(inicializa)                                   // 000100-INICIALIZACION
                .next(porModo)
                    .on("REGRESA_FECHA").to(regresaFecha)            // 000150-REGRESO-FECHA
                .from(porModo).on("SINCRONIZA_S500").to(sincronizaS500)  // 000140-MANTEN-FECHA-S500
                .from(porModo).on("*").to(depura)                    // 000200-PROCESO
                .end()
                .build();
    }

    @Bean
    JobExecutionDecider porModo() {
        return (job, step) -> new FlowExecutionStatus(
                ModoDepuracion.de(job.getJobParameters().getLong("taskValue", 0L)).name());
    }
}

@Service
@RequiredArgsConstructor
public class FechaProcesoService {

    private final LibreriaControl libCtl;            // CONSISDIA / MANTSISDIA IN LIBCTL
    private final P196Properties props;

    /** 000100-INICIALIZACION: fecha de proceso 151 del sistema; si S151 no tiene B01, se crea. */
    @Transactional
    public LocalDate fechaProceso151(int sistema, int csi) {
        var r = libCtl.consisdia(sistema, csi);
        if (r.ok()) return r.fecPro151();
        if (sistema == 151 && r.resultado() == 1) {                 // registro no existe
            var semilla = props.fechaSemillaB01();                 // p196.fecha-semilla-b01: 2015-05-25
            var alta = libCtl.mantsisdia(19, sistema, csi, semilla, semilla, semilla);
            if (!alta.ok()) throw new ProcesoAbortadoException("ERROR AL CREAR B01SISDIA");  // cambio deliberado
            return semilla;    // el COBOL no copia la semilla a WKS-FECPRO151 (ver riesgo)
        }
        throw new ProcesoAbortadoException("ERROR EN LLAMADO EN L001");  // STATUS OF MYSELF = -1
    }
}

/** 000210-PROYFEC-ANTHAB: THECALENDAR función 15, formato 13, desplazamiento 1. */
@Component
@RequiredArgsConstructor
public class CalendarioBancario {

    private final CalendarioClient locsup;   // adaptador de THECALENDAR IN LOCSUP

    public LocalDate fechaAnterior(LocalDate fechaProceso) {
        var r = locsup.thecalendar(15, fechaProceso, 1, 13);
        if (r.funcion() > 0) {
            // El COBOL arma este texto pero no lo envía a LIB-DISP antes de STATUS -1.
            throw new ProcesoAbortadoException(
                "FUNCION 15 ERROR # %d EN LLAMADO DE CALENDAR %s 00000001".formatted(r.funcion(), fechaProceso));
        }
        return r.fecha();   // WKS-FEC-ANT
    }
}

/** 000200-PROCESO con fecha > 0 + 000230-ELIMINA-ACTUALIZA. */
public void puntual(ParametrosDepuracion p) {
    // 196 y 197 se eliminan (función 22); cualquier otro proceso se actualiza (función 37) con REGFIN
    boolean elimina = p.numProceso() == 196 || p.numProceso() == 197;   // p196.procesos-eliminables
    var r = libCtl.b05Procesos(elimina ? 22 : 37,
                               p.sistema(), p.fecha(), p.numProceso(), p.numRegIni(),
                               elimina ? null : p.numRegFin());
    if (r.ok()) {
        bitacora.info("SE ELIMINO/ACT CORRECTAMENTE B05 CON FECHA: %s SISTEMA: %d Y NUM. PROC : %d"
                .formatted(p.fecha(), p.sistema(), p.numProceso()));
    } else {
        bitacora.info("NO SE ELIMINO/ACT B05 CON FECHA: %s SISTEMA: %d NUM. PROC : %d"
                .formatted(p.fecha(), p.sistema(), p.numProceso()));   // no aborta: solo informa
    }
}

/** 000200-PROCESO sin fecha: depuración masiva. */
public void masiva(ParametrosDepuracion p, LocalDate fechaProceso151) {
    LocalDate umbral = calendario.fechaAnterior(fechaProceso151);       // 000210
    if (p.sistema() == 151) {
        props.procesos().s151().forEach(proc -> depuraProceso(p.sistema(), proc, umbral));
        eliminaPrelinea500(umbral);                                     // 000220-ELI-B05-PRELIN500
        marcaP196Prelinea();                                            // 000230-ACT-B05-P196-PRELINEA
    } else {
        props.procesos().otros().forEach(proc -> depuraProceso(p.sistema(), proc, umbral));
    }
}

public interface ProcesoB05Repository extends JpaRepository<ProcesoB05, ProcesoB05Id> {

    /** LOCK FIRST/NEXT B05SXPROCESO AT ... sustituido por un DELETE con el mismo predicado. */
    @Modifying
    @Query("""
        delete from ProcesoB05 b
         where b.sistema = :sis and b.numProceso = :proc and b.numRegIni = :regIni
           and b.fchPro < :umbral and b.fchPro > :fechaMinima""")
    int depura(int sis, int proc, int regIni, LocalDate umbral, int fechaMinima);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<ProcesoB05> findFirstBySistemaAndFchProAndNumProceso(int sis, LocalDate fch, int proc);
}

/** 000220-ELIMINA-B05: una transacción por proceso, como el BEGIN/END-TRANSACTION NO-AUDIT. */
@Transactional
public void depuraProceso(int sistema, int proceso, LocalDate umbral) {
    int regIni = (proceso == props.procesoRegistroInicial1()) ? 1 : 0;   // 196 busca NUMREGINI = 1
    int borrados = repo.depura(sistema, proceso, regIni, umbral, props.fechaMinimaValida() - 1);
    log.info("Proceso {}: {} B05 depurados", proceso, borrados);
    if (proceso == props.procesoMarcaReinicio()) {                       // 197: se conserva el del umbral
        repo.findFirstBySistemaAndFchProAndNumProceso(sistema, umbral, proceso)
            .ifPresent(b -> b.setFchIni(1));                             // STORE
    }
}

/** 000220-ELI-B05-PRELIN500: dos días hacia atrás y eliminación vía librería de control. */
void eliminaPrelinea500(LocalDate umbral) {
    LocalDate umbral2 = calendario.fechaAnterior(umbral);        // reproyecta sobre WKS-FEC-ANT
    var r = libCtl.b05Procesos(22, 500, umbral2, 1, 3, null);    // sistema 500, proceso 001, reg. ini. 3
    if (!r.ok()) log.warn("B05 prelínea 500 no eliminado: {}", r);   // el COBOL no revisa el resultado
}

/** 000230-ACT-B05-P196-PRELINEA: el 196 del día contable queda con NUMREGINI = 1. */
@Transactional
void marcaP196Prelinea() {
    LocalDate fecCon = libCtl.consisdia(151, csi).fecCon();
    repo.findFirstBySistemaAndFchProAndNumProceso(151, fecCon, 196)
        .ifPresent(b -> b.setNumRegIni(1));                      // la próxima depuración lo alcanzará
}

/** 000140-MANTEN-FECHA-S500: solo si aún no existe el B05 196 de S151 con registro inicial 0. */
@Component
@RequiredArgsConstructor
public class SincronizaFechaS500Tasklet implements Tasklet {

    private final ProcesoB05Repository repo;
    private final LibreriaControl libCtl;

    @Override
    @Transactional
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        if (repo.existsBySistemaAndNumProcesoAndNumRegIni(151, 196, 0)) return RepeatStatus.FINISHED;
        int csi = csiDelHost();
        LocalDate fecConS500 = libCtl.consisdia(500, csi).orElseThrow("ERROR CONSULTA FECHA 500").fecCon();
        libCtl.consisdia(151, csi).orElseThrow("ERROR EN CONSULTA 151");
        // Las tres fechas de S151 reciben el mismo valor: la fecha contable de S500.
        libCtl.mantsisdia(37, 151, csi, fecConS500, fecConS500, fecConS500)
              .orElseThrow("ERROR AL GRABAR FECHA 151");
        libCtl.b05Procesos(19, 151, fecConS500, 196, 0, null)           // alta del B05 196
              .orElseThrow("ERROR AL CREAR REG B05 196");
        return RepeatStatus.FINISHED;
    }
}
